#!/usr/bin/env python3
"""A small dutree-compatible disk usage tree printer.

This is an original reimplementation based on observed CLI behavior.
"""

import os
import stat
import sys
from dataclasses import dataclass, field
from typing import List, Optional, Tuple, Dict

VERSION = "dutree version 0.2.18"
BAR_WIDTH = 32
AGGR_DEFAULT = 1024 * 1024

HELP_TEMPLATE = """Usage: {prog} [options] <path> [<path>..]

Options:
    -d, --depth [DEPTH] show directories up to depth N (def 1)
    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)
    -s, --summary       equivalent to -da, or -d1 -a1M
    -u, --usage         report real disk usage instead of file size
    -b, --bytes         print sizes in bytes
    -f, --files-only    skip directories for a fast local overview
    -x, --exclude NAME  exclude matching files or directories
    -H, --no-hidden     exclude hidden files
    -A, --ascii         ASCII characters only, no colors
    -h, --help          show help
    -v, --version       print version number"""


@dataclass
class Options:
    depth: Optional[int] = None          # None means unlimited; bare -d means 1
    aggr: int = 0                       # default: no positive aggregation
    summary: bool = False
    usage: bool = False
    bytes: bool = False
    files_only: bool = False
    no_hidden: bool = False
    ascii: bool = False
    help: bool = False
    version: bool = False
    excludes: List[str] = field(default_factory=list)


@dataclass
class Node:
    name: str
    path: str
    size: int
    is_dir: bool = False
    children: List["Node"] = field(default_factory=list)
    aggregate: bool = False
    mode: int = 0


def print_help(prog: str, out=sys.stdout) -> None:
    print(HELP_TEMPLATE.format(prog=prog), file=out)


def option_error(prog: str, msg: str) -> int:
    print_help(prog, sys.stdout)
    print(msg, file=sys.stderr)
    return 1


def parse_depth_value(s: Optional[str]) -> int:
    if s is None:
        return 1
    try:
        # Rust usize parsing accepts digits only for the cases we care about.
        if not s.isdigit():
            raise ValueError
        return int(s, 10)
    except Exception:
        return 1


def parse_aggr_value(s: Optional[str]) -> Tuple[Optional[int], Optional[str]]:
    if s is None:
        return AGGR_DEFAULT, None
    if s == "":
        return None, s
    mult = 1
    num = s
    last = s[-1]
    if not last.isdigit():
        num = s[:-1]
        if num == "" or not num.isdigit():
            return None, s
        l = last.lower()
        if l == "k":
            mult = 1024
        elif l == "m":
            mult = 1024 ** 2
        elif l == "g":
            mult = 1024 ** 3
        elif l == "t":
            mult = 1024 ** 4
        else:
            mult = 1
    else:
        if not num.isdigit():
            return None, s
    return int(num, 10) * mult, None


def parse_args(argv: List[str]) -> Tuple[Optional[Options], Optional[List[str]], int]:
    prog = argv[0]
    opts = Options()
    paths: List[str] = []
    i = 1
    stop_options = False
    no_arg_longs = {
        "summary": "summary",
        "usage": "usage",
        "bytes": "bytes",
        "files-only": "files_only",
        "no-hidden": "no_hidden",
        "ascii": "ascii",
        "help": "help",
        "version": "version",
    }

    while i < len(argv):
        arg = argv[i]
        if stop_options or not arg.startswith("-") or arg == "-":
            paths.append(arg)
            i += 1
            continue
        if arg == "--":
            stop_options = True
            i += 1
            continue

        if arg.startswith("--"):
            body = arg[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                has_eq = True
            else:
                name, val = body, None
                has_eq = False

            if name in no_arg_longs:
                if has_eq:
                    return None, None, option_error(prog, f"Option '{name}' does not take an argument")
                setattr(opts, no_arg_longs[name], True)
                i += 1
                continue
            if name == "depth":
                opts.depth = parse_depth_value(val if has_eq else None)
                i += 1
                continue
            if name == "aggr":
                value, bad = parse_aggr_value(val if has_eq else None)
                if bad is not None:
                    print(f"invalid argument '{bad}'", file=sys.stderr)
                    return None, None, 1
                opts.aggr = value if value is not None else AGGR_DEFAULT
                i += 1
                continue
            if name == "exclude":
                if has_eq:
                    opts.excludes.append(val if val is not None else "")
                    i += 1
                else:
                    if i + 1 >= len(argv):
                        return None, None, option_error(prog, "Argument to option 'exclude' missing")
                    opts.excludes.append(argv[i + 1])
                    i += 2
                continue
            return None, None, option_error(prog, f"Unrecognized option: '{name}'")

        # short option cluster
        cluster = arg[1:]
        j = 0
        consumed_token = False
        while j < len(cluster):
            ch = cluster[j]
            rest = cluster[j + 1:]
            if ch == "s":
                opts.summary = True
            elif ch == "u":
                opts.usage = True
            elif ch == "b":
                opts.bytes = True
            elif ch == "f":
                opts.files_only = True
            elif ch == "H":
                opts.no_hidden = True
            elif ch == "A":
                opts.ascii = True
            elif ch == "h":
                opts.help = True
            elif ch == "v":
                opts.version = True
            elif ch == "d":
                if rest:
                    opts.depth = parse_depth_value(rest)
                    consumed_token = True
                    break
                if i + 1 < len(argv) and not argv[i + 1].startswith("-"):
                    opts.depth = parse_depth_value(argv[i + 1])
                    i += 1
                else:
                    opts.depth = 1
                consumed_token = True
                break
            elif ch == "a":
                if rest:
                    val = rest
                    value, bad = parse_aggr_value(val)
                    if bad is not None:
                        print(f"invalid argument '{bad}'", file=sys.stderr)
                        return None, None, 1
                    opts.aggr = value if value is not None else AGGR_DEFAULT
                    consumed_token = True
                    break
                if i + 1 < len(argv) and not argv[i + 1].startswith("-"):
                    val = argv[i + 1]
                    value, bad = parse_aggr_value(val)
                    if bad is not None:
                        print(f"invalid argument '{bad}'", file=sys.stderr)
                        return None, None, 1
                    opts.aggr = value if value is not None else AGGR_DEFAULT
                    i += 1
                else:
                    opts.aggr = AGGR_DEFAULT
                consumed_token = True
                break
            elif ch == "x":
                if rest:
                    opts.excludes.append(rest)
                    consumed_token = True
                    break
                if i + 1 >= len(argv):
                    return None, None, option_error(prog, "Argument to option 'x' missing")
                opts.excludes.append(argv[i + 1])
                i += 1
                consumed_token = True
                break
            else:
                return None, None, option_error(prog, f"Unrecognized option: '{ch}'")
            j += 1
        i += 1

    if opts.summary:
        opts.depth = 1
        opts.aggr = AGGR_DEFAULT

    if not paths:
        paths = ["."]
    return opts, paths, 0


def stat_size(st: os.stat_result, usage: bool) -> int:
    if usage:
        return int(getattr(st, "st_blocks", 0)) * 512
    return int(st.st_size)


def display_name_for_path(path: str) -> str:
    norm = os.path.normpath(path)
    base = os.path.basename(norm)
    if base:
        return base
    return norm or path


def permission_name(path: str) -> str:
    return display_name_for_path(path)


def should_skip(name: str, opts: Options) -> bool:
    if opts.no_hidden and name.startswith("."):
        return True
    if name in opts.excludes:
        return True
    return False


def lstat_node(path: str, opts: Options) -> Optional[Tuple[os.stat_result, bool, int]]:
    try:
        st = os.lstat(path)
    except OSError:
        return None
    is_dir = stat.S_ISDIR(st.st_mode)
    return st, is_dir, stat_size(st, opts.usage)


def build_node(path: str, opts: Options, name: Optional[str] = None) -> Node:
    nm = display_name_for_path(path) if name is None else name
    info = lstat_node(path, opts)
    if info is None:
        return Node(nm, path, 0, False)
    st, is_dir, own = info
    node = Node(nm, path, own, is_dir=is_dir, mode=st.st_mode)

    if not is_dir:
        return node

    try:
        entries = list(os.scandir(path))
    except PermissionError:
        print(f"Couldn't read {permission_name(path)} (PermissionDenied)", file=sys.stderr)
        return node
    except OSError as e:
        # Match the common Rust debug name for permission errors; otherwise show the errno name if known.
        kind = "PermissionDenied" if getattr(e, "errno", None) == 13 else e.__class__.__name__
        print(f"Couldn't read {permission_name(path)} ({kind})", file=sys.stderr)
        return node

    for ent in entries:
        child_name = ent.name
        if should_skip(child_name, opts):
            continue
        child_path = os.path.join(path, child_name)
        child_info = lstat_node(child_path, opts)
        if child_info is None:
            continue
        child_st, child_is_dir, child_own = child_info
        if opts.files_only and child_is_dir:
            continue
        if opts.files_only:
            child = Node(child_name, child_path, child_own, is_dir=False, mode=child_st.st_mode)
        else:
            child = build_node(child_path, opts, child_name)
        node.children.append(child)
        node.size += child.size
    return node


def sort_tree(node: Node) -> None:
    for ch in node.children:
        sort_tree(ch)
    node.children.sort(key=lambda n: n.size, reverse=True)


def make_collection(paths: List[str], opts: Options) -> Node:
    if len(paths) == 1:
        root = build_node(paths[0], opts)
        sort_tree(root)
        return root
    root = Node("<collection>", "", 0, is_dir=True)
    for p in paths:
        ch = build_node(p, opts)
        sort_tree(ch)
        root.children.append(ch)
        root.size += ch.size
    root.children.sort(key=lambda n: n.size, reverse=True)
    return root


def human_size(n: int, bytes_flag: bool) -> str:
    if bytes_flag or n < 1024:
        return f"{n} B"
    units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
    value = float(n)
    idx = -1
    while value >= 1024.0 and idx + 1 < len(units):
        value /= 1024.0
        idx += 1
        # Keep 1024.00 KiB just below a MiB, matching threshold-before-rounding behavior.
        if n < 1024 ** (idx + 2):
            break
    if idx < 0:
        return f"{n} B"
    return f"{value:.2f} {units[idx]}"


def percent(child_size: int, parent_size: int) -> int:
    if parent_size <= 0:
        return 0
    return int((child_size * 100) // parent_size)


def bar_units(size: int, max_size: int, width: int = BAR_WIDTH) -> int:
    if max_size <= 0 or size <= 0:
        return 0
    if size == max_size:
        return width
    # The original effectively uses one more bucket than displayed columns, then
    # shifts down by one; this makes near-maximum entries 31/32 columns.
    val = (size * (width + 1)) // max_size - 1
    if val < 0:
        return 0
    if val > width:
        return width
    return int(val)


def visible_children(node: Node, opts: Options) -> List[Node]:
    if not node.children:
        return []
    if opts.aggr <= 0:
        return node.children
    shown: List[Node] = []
    agg_size = 0
    for ch in node.children:
        if ch.size < opts.aggr:
            agg_size += ch.size
        else:
            shown.append(ch)
    if agg_size > 0:
        shown.append(Node("<aggregated>", "", agg_size, is_dir=False, aggregate=True))
    return shown


class Colorizer:
    def __init__(self, enabled: bool):
        self.enabled = enabled
        self.codes: Dict[str, str] = {}
        self.exts: List[Tuple[str, str]] = []
        if enabled:
            self._parse(os.environ.get("LS_COLORS", ""))

    def _parse(self, val: str) -> None:
        for part in val.split(":"):
            if not part or "=" not in part:
                continue
            k, v = part.split("=", 1)
            if not v:
                continue
            if k.startswith("*."):
                self.exts.append((k[1:], v))  # store suffix including dot
            else:
                self.codes[k] = v

    def code_for(self, node: Node) -> Optional[str]:
        if not self.enabled or node.aggregate or not self.codes and not self.exts:
            return None
        # Color classification follows normal metadata where possible: symlinks to
        # directories look like directories, broken symlinks are left plain.
        is_dir_color = False
        is_regular = False
        try:
            st = os.stat(node.path)
            is_dir_color = stat.S_ISDIR(st.st_mode)
            is_regular = stat.S_ISREG(st.st_mode)
        except OSError:
            is_dir_color = node.is_dir
            is_regular = False
        if is_dir_color and "di" in self.codes:
            return self.codes["di"]
        # Extension patterns override generic file coloring in observed behavior.
        for suffix, code in self.exts:
            if node.name.endswith(suffix):
                return code
        if is_regular and "fi" in self.codes:
            return self.codes["fi"]
        return None

    def color_name(self, node: Node, name: str) -> str:
        code = self.code_for(node)
        if not code:
            return name
        return f"\033[{code}m{name}\033[0m"


def left_field(prefix: str, connector: str, node: Node, colorizer: Colorizer) -> str:
    base_prefix = prefix + connector
    max_name = max(0, 25 - len(base_prefix))
    name = node.name[:max_name]
    visual_len = len(base_prefix) + len(name)
    pad = max(0, 26 - visual_len)
    return base_prefix + colorizer.color_name(node, name) + (" " * pad)


def shade_char_for_child_depth(child_depth: int) -> str:
    # child_depth: root children are 1. Their children use light shade.
    shades = ["░", "▒", "▓"]
    idx = child_depth - 2
    if idx < 0:
        idx = 0
    if idx >= len(shades):
        idx = len(shades) - 1
    return shades[idx]


def update_unicode_cells(parent_cells: str, child: Node, parent: Node, child_depth: int) -> str:
    active = parent_cells.count("█")
    if active <= 0:
        return parent_cells
    if parent.size <= 0 or child.size <= 0:
        new_active = 0
    elif child.size == parent.size:
        new_active = active
    elif active == 1:
        # A one-column branch remains visible for non-zero descendants.
        new_active = 1
    else:
        new_active = (child.size * (active + 1)) // parent.size - 1
        if new_active < 0:
            new_active = 0
        if new_active > active:
            new_active = active
    replace = active - new_active
    if replace <= 0:
        return parent_cells
    # Active cells are a trailing run of full blocks.
    start = len(parent_cells) - active
    shade = shade_char_for_child_depth(child_depth)
    return parent_cells[:start] + (shade * replace) + ("█" * new_active)


def make_line(prefix: str, connector: str, node: Node, parent: Node, cells: str,
              opts: Options, colorizer: Colorizer) -> str:
    lf = left_field(prefix, connector, node, colorizer)
    pct = percent(node.size, parent.size)
    size_s = human_size(node.size, opts.bytes)
    tail = f"{pct:4d}%{size_s:>14}"
    return f"{lf}│ {cells}│{tail}"


def render_children(parent: Node, opts: Options, colorizer: Colorizer, out_lines: List[str],
                    prefix: str = "", depth: int = 0, parent_cells: Optional[str] = None) -> None:
    if opts.depth is not None and depth >= opts.depth:
        return
    children = visible_children(parent, opts)
    if not children:
        return

    top_level = depth == 0
    max_size = max((c.size for c in children), default=0)

    for idx, ch in enumerate(children):
        last = idx == len(children) - 1
        connector = "└─ " if last else "├─ "
        if top_level:
            units = bar_units(ch.size, max_size, BAR_WIDTH)
            fill = "#" if opts.ascii else "█"
            cells = (" " * (BAR_WIDTH - units)) + (fill * units)
        else:
            if opts.ascii:
                cells = parent_cells if parent_cells is not None else (" " * BAR_WIDTH)
            else:
                cells = update_unicode_cells(parent_cells or (" " * BAR_WIDTH), ch, parent, depth + 1)
        out_lines.append(make_line(prefix, connector, ch, parent, cells, opts, colorizer))

        if ch.children:
            next_prefix = prefix + ("   " if last else "│  ")
            render_children(ch, opts, colorizer, out_lines, next_prefix, depth + 1, cells)


def render(root: Node, opts: Options) -> str:
    colorizer = Colorizer(enabled=(not opts.ascii))
    lines = [f"[ {root.name} {human_size(root.size, opts.bytes)} ]"]
    render_children(root, opts, colorizer, lines)
    return "\n".join(lines) + "\n"


def main(argv: List[str]) -> int:
    opts, paths, code = parse_args(argv)
    if code != 0:
        return code
    assert opts is not None and paths is not None

    # Validate all requested roots using follows-symlink existence, matching the
    # observed treatment of broken symlink roots.
    for p in paths:
        if not os.path.exists(p):
            print(f"path {p} doesn't exist", file=sys.stderr)
            return 1

    if opts.help:
        print_help(argv[0], sys.stdout)
        return 0
    if opts.version:
        print(VERSION)
        return 0

    root = make_collection(paths, opts)
    sys.stdout.write(render(root, opts))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
